"""Real themes/Monaco/profile/extensions, with explicit QA text and a real Node extension."""
import argparse,io,json,shutil,sys,tempfile,threading,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from PIL import Image,ImageDraw
from playwright.sync_api import sync_playwright,expect

def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);p.add_argument('--installed-from',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=True);checks=[];errors=[];metrics={}
 def passed(s):checks.append(s);print('PASS',s,flush=True)
 with tempfile.TemporaryDirectory(prefix='zenit-refinement-') as tmp:
  base=Path(tmp);ws=base/'project';ws.mkdir();(ws/'Example.java').write_text('public class Example {\n  public static void main(String[] args) {\n    System.out.println("Hola desde Zénit");\n  }\n}\n',encoding='utf-8');profile=base/'profile';dest=profile/'extensions';dest.mkdir(parents=True);index=json.loads((a.installed_from/'installed.json').read_text(encoding='utf-8-sig'));info=index['zhuangtongfa.material-theme'];shutil.copytree(a.installed_from/info['directory'],dest/info['directory']);(dest/'installed.json').write_text(json.dumps({'zhuangtongfa.material-theme':info}));app=Application(ROOT,ws,data_dir=profile);app.workspace.trusted=True;app.features.studio.update({'onboarded':True,'displayName':'Perfil de prueba'});app.features.prefs.update({'general.showWelcome':False,'appearance.motion':False,'updates.automatic':False,'extensions.checkUpdatesOnOpen':False})
  package=io.BytesIO()
  with zipfile.ZipFile(package,'w') as z:
   z.writestr('extension/package.json',json.dumps({'publisher':'qa','name':'controls','version':'1','main':'main.cjs'}));z.writestr('extension/main.cjs',"const v=require('vscode');exports.activate=()=>v.commands.registerCommand('qa.open',async(id,...args)=>{await v.commands.executeCommand(id,...args);return 'acknowledged';});")
  app.features.extensions.install(app.features.extensions.inspect_bytes(package.getvalue())['ticket'],True);app.features.extension_runtime.start(app.workspace,'qa.controls',True)
  server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start()
  try:
   with sync_playwright() as pw:
    browser=pw.chromium.launch(channel='msedge',headless=True,args=['--use-angle=swiftshader','--enable-unsafe-swiftshader']);context=browser.new_context(viewport={'width':1672,'height':917});page=context.new_page();page.on('pageerror',lambda e:errors.append(str(e)));context.grant_permissions(['clipboard-read','clipboard-write'])
    def inject(route):
     response=route.fetch();route.fulfill(response=response,body=response.text()+'\nwindow.__qa={get editor(){return editor},get platform(){return platformUI},get studio(){return studio},appendChat,openFile};')
    page.route('**/src/app.js',inject);page.goto(f'http://127.0.0.1:{server.server_port}');page.wait_for_function('window.lumen?.ready');page.evaluate('async()=>{await __qa.openFile("Example.java");await __qa.platform.applyExtensionTheme(__qa.platform.extensionThemes.findIndex(t=>t.label==="One Dark Pro Darker"));}')
    rich='### Medidas del formato\n\n**Datos de prueba**, sin ejecución.\n\n| Campo | Bytes |\n| --- | ---: |\n| Sal | 16 |\n| Nonce | 12 |\n\n- Valida la longitud.\n- Conserva el valor original.\n\n```java\n  System.out.println("Hola");\n```\n\n<script>window.__unsafe=true</script>\n[Enlace inválido](javascript:alert(1))\n[Documentación](https://example.com/docs)'
    page.evaluate('(text)=>{const node=__qa.appendChat(text,"assistant","Respuesta de prueba de interfaz");__qa.platform.voice.attach(node,text)}',rich);expect(page.locator('.message-table tbody tr')).to_have_count(2);expect(page.locator('.message-rich h4')).to_have_text('Medidas del formato');expect(page.locator('.message-rich ul li')).to_have_count(2);assert page.evaluate('!window.__unsafe&&!document.querySelector(".message-rich script")&&!document.querySelector(".message-rich img")');assert page.locator('.message-rich a').count()==1;passed('Tables, headings, lists and links render real response text without executing HTML or loading images')
    expect(page.locator('.message-code pre')).to_have_text('  System.out.println("Hola");');page.locator('.copy-code').click();assert page.evaluate('navigator.clipboard.readText()')=='  System.out.println("Hola");';passed('Copy preserves exact fenced code and the voice action still attaches to the answer');page.screenshot(path=str(a.output/'melody-markdown-dark.png'))
    page.locator('.monaco-editor').first.click(button='right',position={'x':240,'y':80});menu=page.locator('.monaco-menu .monaco-action-bar.vertical').first;expect(menu).to_be_visible();bounds=menu.bounding_box();metrics['contextMenu']=bounds;print('MENU',bounds,flush=True);page.screenshot(path=str(a.output/'menu-before-check.png'));assert bounds['width']<=370 and bounds['height']<600 and bounds['y']>=0 and bounds['y']+bounds['height']<=917;assert menu.locator('.zenit-menu-glyph').count()>=7;assert menu.locator('.action-menu-item').first.bounding_box()['height']<=30;passed('The actual Monaco context menu is compact, themed and has consistent SVG icons');page.screenshot(path=str(a.output/'editor-context-dark.png'));page.keyboard.press('Escape');assert page.evaluate('__qa.editor.view.getModel().getLanguageId()')=='java';page.evaluate('__qa.editor.split("Example.java")');page.evaluate('__qa.platform.savePreference("editor.fontSize",15)');assert page.evaluate('document.documentElement.dataset.extensionTheme.endsWith("One Dark Pro Darker")');passed('The selected theme and real Java highlighting survive a split and editor setting change')
    # Real extension -> Node host -> backend -> renderer -> acknowledgement.
    for command,selector in [('workbench.action.selectTheme','.theme-picker'),('workbench.action.showCommands','#palette-backdrop:not(.hidden)'),('workbench.action.quickOpen','#palette-backdrop:not(.hidden)'),('workbench.action.openSettings','.settings-overlay')]:
     page.evaluate('id=>{window.__commandDone=null;window.__commandError=null;__qa.platform.api("/extensions/runtime/request",{id:"qa.controls",method:"command",command:"qa.open",arguments:[id]}).then(x=>window.__commandDone=x.result).catch(e=>window.__commandError=e.message)}',command);page.wait_for_function('window.__commandDone!==null||window.__commandError!==null');assert page.evaluate('__commandDone')=='acknowledged',page.evaluate('__commandError');expect(page.locator(selector)).to_be_visible();page.keyboard.press('Escape')
    passed('Four VS Code workbench commands open real Zénit controls from a real Node extension and acknowledge completion')
    page.evaluate('()=>{window.__themes=__qa.platform.extensionThemes;__qa.platform.extensionThemes=[];window.__commandError=null;__qa.platform.api("/extensions/runtime/request",{id:"qa.controls",method:"command",command:"qa.open",arguments:["workbench.action.selectTheme"]}).catch(e=>window.__commandError=e.message)}');page.wait_for_function('window.__commandError!==null');assert 'No hay temas' in page.evaluate('__commandError');page.evaluate('__qa.platform.extensionThemes=__themes');passed('An empty theme catalogue rejects the extension command even when a previous hidden picker remains in the DOM')
    page.evaluate('__qa.studio.editProfile()');expect(page.locator('.profile-form')).to_be_visible();box=page.locator('#modal').bounding_box();print('PROFILE',box,flush=True);page.screenshot(path=str(a.output/'profile-before-check.png'));assert box['height']<460;metrics['profile']=box;fixture=base/'avatar.png';image=Image.new('RGB',(320,180),'#ad9af6');ImageDraw.Draw(image).rectangle((10,20,130,160),fill='#76c9dc');image.save(fixture);page.locator('#profile-picture').set_input_files(str(fixture));page.wait_for_function('!document.querySelector("#profile-zoom").disabled');page.locator('#profile-zoom').fill('1.6');page.locator('#profile-name').fill('Nuevo perfil');page.screenshot(path=str(a.output/'profile-dark.png'));page.locator('.profile-form button[type=submit],.profile-form .primary-button').click();page.evaluate('__qa.studio.editProfile()');expect(page.locator('#profile-name')).to_have_value('Nuevo perfil');assert page.evaluate('__qa.studio.profile.avatar').startswith('data:image/webp;base64,');page.keyboard.press('Escape');passed('The compact two-column profile saves a real cropped WebP and restores the name')
    page.evaluate('__qa.platform.extensions()');page.wait_for_selector('.extension-card');hero=page.locator('.extension-hero').bounding_box();metrics['extensionHero']=hero;assert hero['height']<=180;expect(page.locator('.extension-theme-swatch')).to_have_attribute('title','One Dark Pro Darker');page.screenshot(path=str(a.output/'extensions-dark.png'));page.locator('.extension-import-shortcut').click();expect(page.locator('#extension-import-form')).to_be_visible();page.keyboard.press('Escape');passed('The smaller catalogue shows the actual selected theme preview and opens the real VSIX inspector')
    for width,height in [(1280,720),(1366,768),(1920,1080)]:
     page.set_viewport_size({'width':width,'height':height});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.evaluate('__qa.studio.editProfile()');assert page.locator('#modal').bounding_box()['height']<height;page.keyboard.press('Escape')
    passed('Catalogue, profile and formatted conversation stay within three desktop sizes')
    page.set_viewport_size({'width':1672,'height':917});page.evaluate('__qa.studio.home()');page.wait_for_selector('.welcome-scene .gpu-ready');canvas=page.evaluate('()=>{window.__canvas=document.querySelector("canvas[data-glass=welcome]");return __canvas.dataset.geometry}');assert canvas=='blender-double-wall';before=page.evaluate('getComputedStyle(document.querySelector(".welcome-sheet"),"::before").backgroundImage');page.screenshot(path=str(a.output/'welcome-dark.png'));page.evaluate('async()=>await __qa.platform.savePreference("appearance.theme","day")');assert page.evaluate('document.querySelector("canvas[data-glass=welcome]")===__canvas');after=page.evaluate('getComputedStyle(document.querySelector(".welcome-sheet"),"::before").backgroundImage');assert before!=after;page.screenshot(path=str(a.output/'welcome-day.png'));passed('Welcome atmosphere follows the active theme while retaining the Blender/Babylon canvas')
    assert not errors,errors;passed('No uncaught JavaScript errors');browser.close()
  finally:server.shutdown();server.server_close();app.features.shutdown();app.runner.shutdown()
 (a.output/'verification.json').write_text(json.dumps({'checks':checks,'errors':errors,'metrics':metrics,'fixture':'QA project, generated avatar and explicit model text; real installed theme and Node extension. Not an external AI quality test.'},indent=2),encoding='utf-8')
if __name__=='__main__':main()
